-- READ-ONLY 2015 exact shared source RH cases with reconstruction target RH NULL and immediate +/-300s RH endpoints.
SELECT o.dateTime target_time,o.outHumidity old_rh,w.outHumidity wh_rh,o.outTemp old_temp,w.outTemp wh_temp,r.outHumidity target_rh,r.outTemp target_temp,rp.outHumidity prev_rh,rn.outHumidity next_rh,e.outHumidity euold_rh,pe.outHumidity eu_rh,pg.outHumidity gw_rh,l.relative_humidity_pct luhamet_rh,l.temperature_c luhamet_temp,ABS(o.outHumidity-(rp.outHumidity+rn.outHumidity)/2) midpoint_delta,(o.outHumidity BETWEEN LEAST(rp.outHumidity,rn.outHumidity) AND GREATEST(rp.outHumidity,rn.outHumidity)) within_range,(SELECT COUNT(*) FROM loucka_reconstruction.reconstruction_changes c WHERE c.target_time=o.dateTime AND c.variable='outHumidity') rh_history_events FROM old_weewx.archive o JOIN weewx_WH1080.archive w ON w.dateTime=o.dateTime JOIN loucka_reconstruction.archive r ON r.dateTime=o.dateTime JOIN loucka_reconstruction.archive rp ON rp.dateTime=o.dateTime-300 JOIN loucka_reconstruction.archive rn ON rn.dateTime=o.dateTime+300 LEFT JOIN `pocasi-loucka.eu_old`.archive e ON e.dateTime=o.dateTime LEFT JOIN `pocasi-loucka.eu`.archive pe ON pe.dateTime=o.dateTime LEFT JOIN `pocasi-loucka.eu_GW1000`.archive pg ON pg.dateTime=o.dateTime LEFT JOIN loucka_reconstruction.reference_observations l ON l.station_id='luhamet_sehradice' AND l.observed_at_utc=o.dateTime WHERE o.dateTime>=1420070400 AND o.dateTime<1451606400 AND o.outHumidity IS NOT NULL AND w.outHumidity IS NOT NULL AND o.outHumidity=w.outHumidity AND r.outHumidity IS NULL AND rp.outHumidity IS NOT NULL AND rn.outHumidity IS NOT NULL AND o.usUnits=17 AND w.usUnits=17 AND o.`interval`=5 AND w.`interval`=5 AND NOT EXISTS(SELECT 1 FROM loucka_reconstruction.reconstruction_changes c WHERE c.target_time=o.dateTime AND c.variable='outHumidity') ORDER BY o.dateTime;
